CREATE TABLE public.assets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    symbol text NOT NULL,
    name text NOT NULL,
    asset_class text DEFAULT 'equity'::text NOT NULL,
    description text,
    last_price_cents bigint DEFAULT 0 NOT NULL,
    market_price_cents bigint DEFAULT 0 NOT NULL,
    fifty_two_week_high_cents bigint,
    fifty_two_week_low_cents bigint,
    pe_ratio numeric(10,4),
    market_cap_cents bigint,
    dividend_yield_pct numeric(8,4),
    history_30d jsonb,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


